LEFT JOIN [ref].[Currency] p1 ON b.[CurrencyKey] = p1.[CurrencyKey]
LEFT JOIN [ref].[CurrencyRegion] p2 ON p1.[CurrencyRegionKey] = p2.[CurrencyRegionKey]
LEFT JOIN [ref].[EnergyTariffChargeType] p3 ON b.[EnergyTariffChargeTypeKey] = p3.[EnergyTariffChargeTypeKey]
LEFT JOIN [dim].[EnergyRateTier] p4 ON b.[EnergyRateTierKey] = p4.[EnergyRateTierKey]
LEFT JOIN [dim].[EnergyRateSchedule] p5 ON p4.[EnergyRateScheduleKey] = p5.[EnergyRateScheduleKey]
LEFT JOIN [dim].[EnergyTariffProvider] p6 ON p5.[EnergyTariffProviderKey] = p6.[EnergyTariffProviderKey]
LEFT JOIN [dim].[EnergyTariffMarket] p7 ON p6.[EnergyTariffMarketKey] = p7.[EnergyTariffMarketKey]
GO

